pragma solidity ^0.8.19;

import {IIRM} from '../interfaces/lending_pool/IIRM.sol';
import {Math} from '@openzeppelin-contracts/utils/math/Math.sol';

contract DoubleSlopeIRM is IIRM {
    // constants
    uint private constant ONE_E18 = 1e18;

    // immutables
    uint public immutable BASE_BORR_RATE_E18; // rate per second
    uint public immutable BORR_RATE_MULTIPLIER_E18; // m1
    uint public immutable JUMP_UTIL_E18; // utilization at which the BORROW_RATE_M2 is applied
    uint public immutable JUMP_MULTIPLIER_E18; // m2

    // constructor
    // NOTE: alway deploy new irm contract when change params to make sure interest will be accrued before changing borrow rate
    constructor(
        uint _baseBorrowRate_e18,
        uint _jumpUtilization_e18,
        uint _borrowRateMultiplier_e18,
        uint _jumpMultiplier_e18
    ) {
        BASE_BORR_RATE_E18 = _baseBorrowRate_e18;
        JUMP_UTIL_E18 = _jumpUtilization_e18;
        BORR_RATE_MULTIPLIER_E18 = _borrowRateMultiplier_e18;
        JUMP_MULTIPLIER_E18 = _jumpMultiplier_e18;
    }

    // functions
    /// @inheritdoc IIRM
    function getBorrowRate_e18(uint _cash, uint _debt) external view override returns (uint borrow_rate_e18) {
        // borrow rate = baseRate + m1 * min(uti, jumpUtil) + m2 * max(0, uti - jumpUtil)
        uint totalAsset = _cash + _debt;
        uint util_e18 = totalAsset == 0 ? 0 : (_debt * ONE_E18) / totalAsset;
        borrow_rate_e18 = BASE_BORR_RATE_E18 + (Math.min(util_e18, JUMP_UTIL_E18) * BORR_RATE_MULTIPLIER_E18) / ONE_E18;
        if (util_e18 > JUMP_UTIL_E18) {
            borrow_rate_e18 += ((util_e18 - JUMP_UTIL_E18) * JUMP_MULTIPLIER_E18) / ONE_E18;
        }
    }
}
"},"contracts/lending_pool/LendingPool.sol":{"content":"// SPDX-License-Identifier: None
pragma solidity ^0.8.19;

import '../common/library/InitErrors.sol';
import {UnderACM} from '../common/UnderACM.sol';
import {ILendingPool} from '../interfaces/lending_pool/ILendingPool.sol';
import {IIRM} from '../interfaces/lending_pool/IIRM.sol';

import {ERC20Upgradeable} from '@openzeppelin-contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol';
import {IERC20Metadata} from '@openzeppelin-contracts/token/ERC20/extensions/IERC20Metadata.sol';
import {SafeERC20} from '@openzeppelin-contracts/token/ERC20/utils/SafeERC20.sol';
import {IERC20} from '@openzeppelin-contracts/token/ERC20/IERC20.sol';
import {MathUpgradeable} from '@openzeppelin-contracts-upgradeable/utils/math/MathUpgradeable.sol';

contract LendingPool is ERC20Upgradeable, ILendingPool, UnderACM {
    using SafeERC20 for IERC20;
    using MathUpgradeable for uint;

    // constants
    uint private constant ONE_E18 = 1e18;
    uint private constant VIRTUAL_SHARES = 1e8;
    uint private constant VIRTUAL_ASSETS = 1;
    bytes32 private constant GUARDIAN = keccak256('guardian');
    bytes32 private constant GOVERNOR = keccak256('governor');

    // immutables
    address public immutable core;

    // storages
    address public underlyingToken; // underlying tokens
    uint public cash; // total cash
    uint public totalDebt; // total debt
    uint public totalDebtShares; // total debt shares
    address public irm; // interest rate model
    uint public lastAccruedTime; // last accrued timestamp
    uint public reserveFactor_e18; // reserve factor
    address public treasury; // treasury address

    // modifiers
    modifier onlyGuardian() {
        ACM.checkRole(GUARDIAN, msg.sender);
        _;
    }

    modifier onlyGovernor() {
        ACM.checkRole(GOVERNOR, msg.sender);
        _;
    }

    modifier onlyCore() {
        _require(msg.sender == core, Errors.NOT_INIT_CORE);
        _;
    }

    modifier accrue() {
        accrueInterest();
        _;
    }

    // constructor
    constructor(address _core, address _acm) UnderACM(_acm) {
        _disableInitializers();
        core = _core;
    }

    // initializer
    /// @dev initialize contract and setup underlying token, name, symbol
    ///     interest rate model, reserver factor and treasury
    /// @param _underlyingToken underlying token address
    /// @param _name lending pool's name
    /// @param _symbol lending pool's symbol
    /// @param _irm interest rate model address
    /// @param _reserveFactor_e18 reserve factor in 1e18 (1e18 = 100%)
    /// @param _treasury treasury address
    function initialize(
        address _underlyingToken,
        string calldata _name,
        string calldata _symbol,
        address _irm,
        uint _reserveFactor_e18,
        address _treasury
    ) external initializer {
        underlyingToken = _underlyingToken;
        __ERC20_init(_name, _symbol);
        irm = _irm;
        treasury = _treasury;
        lastAccruedTime = block.timestamp;
        reserveFactor_e18 = _reserveFactor_e18;
        // approve core to enable flashloan
        IERC20(_underlyingToken).safeApprove(core, type(uint).max);
    }

    // functions
    /// @inheritdoc ERC20Upgradeable
    function decimals() public view override returns (uint8) {
        return IERC20Metadata(underlyingToken).decimals();
    }

    /// @inheritdoc ILendingPool
    function mint(address _receiver) external onlyCore accrue returns (uint shares) {
        uint _cash = cash;
        uint newCash = IERC20(underlyingToken).balanceOf(address(this));
        uint amt = newCash - _cash;
        shares = _toShares(amt, _cash + totalDebt, totalSupply());
        _require(shares != 0, Errors.ZERO_VALUE);
        _mint(_receiver, shares);
        cash = newCash;
    }

    /// @inheritdoc ILendingPool
    function burn(address _receiver) external onlyCore accrue returns (uint amt) {
        uint sharesToBurn = balanceOf(address(this));
        uint _cash = cash;
        _require(sharesToBurn != 0, Errors.ZERO_VALUE);
        amt = _toAmt(sharesToBurn, _cash + totalDebt, totalSupply());
        _require(amt <= _cash, Errors.NOT_ENOUGH_CASH);
        unchecked {
            cash = _cash - amt;
        }
        _burn(address(this), sharesToBurn);
        IERC20(underlyingToken).safeTransfer(_receiver, amt);
    }

    /// @inheritdoc ILendingPool
    function borrow(address _receiver, uint _amt) external onlyCore accrue returns (uint shares) {
        _require(_amt <= cash, Errors.NOT_ENOUGH_CASH);
        uint _totalDebt = totalDebt;
        shares = _totalDebt > 0 ? _amt.mulDiv(totalDebtShares, _totalDebt, MathUpgradeable.Rounding.Up) : _amt;
        totalDebtShares += shares;
        totalDebt = _totalDebt + _amt;
        cash -= _amt;
        IERC20(underlyingToken).safeTransfer(_receiver, _amt);
    }

    /// @inheritdoc ILendingPool
    function repay(uint _shares) external onlyCore accrue returns (uint amt) {
        uint _totalDebtShares = totalDebtShares;
        uint _totalDebt = totalDebt;
        amt = _shares.mulDiv(_totalDebt, _totalDebtShares, MathUpgradeable.Rounding.Up);
        uint newCash = IERC20(underlyingToken).balanceOf(address(this));
        _require(amt <= newCash - cash, Errors.INVALID_AMOUNT_TO_REPAY);
        totalDebtShares = _totalDebtShares - _shares;
        totalDebt = _totalDebt > amt ? _totalDebt - amt : 0;
        cash = newCash;
    }

    /// @inheritdoc ILendingPool
    function syncCash() external accrue onlyCore returns (uint newCash) {
        newCash = IERC20(underlyingToken).balanceOf(address(this));
        _require(newCash >= cash, Errors.INVALID_AMOUNT_TO_REPAY); // flash not repay
        cash = newCash;
    }

    /// @inheritdoc ILendingPool
    function accrueInterest() public {
        uint _lastAccruedTime = lastAccruedTime;
        if (block.timestamp != _lastAccruedTime) {
            uint _totalDebt = totalDebt;
            uint _cash = cash;
            uint borrowRate_e18 = IIRM(irm).getBorrowRate_e18(_cash, _totalDebt);
            uint accruedInterest = (borrowRate_e18 * (block.timestamp - _lastAccruedTime) * _totalDebt) / ONE_E18;
            uint reserve = (accruedInterest * reserveFactor_e18) / ONE_E18;
            if (reserve > 0) {
                _mint(treasury, _toShares(reserve, _cash + _totalDebt + accruedInterest - reserve, totalSupply()));
            }
            totalDebt = _totalDebt + accruedInterest;
            lastAccruedTime = block.timestamp;
        }
    }

    /// @inheritdoc ILendingPool
    function debtAmtToShareStored(uint _amt) public view returns (uint shares) {
        shares = totalDebt > 0 ? _amt.mulDiv(totalDebtShares, totalDebt, MathUpgradeable.Rounding.Up) : _amt;
    }

    /// @inheritdoc ILendingPool
    function debtAmtToShareCurrent(uint _amt) external accrue returns (uint shares) {
        shares = debtAmtToShareStored(_amt);
    }

    /// @inheritdoc ILendingPool
    function debtShareToAmtStored(uint _shares) public view returns (uint amt) {
        amt = totalDebtShares > 0 ? _shares.mulDiv(totalDebt, totalDebtShares, MathUpgradeable.Rounding.Up) : 0;
    }

    /// @inheritdoc ILendingPool
    function debtShareToAmtCurrent(uint _shares) external accrue returns (uint amt) {
        amt = debtShareToAmtStored(_shares);
    }

    /// @inheritdoc ILendingPool
    function toShares(uint _amt) public view returns (uint shares) {
        shares = _toShares(_amt, totalAssets(), totalSupply());
    }

    /// @inheritdoc ILendingPool
    function toAmt(uint _shares) public view returns (uint amt) {
        amt = _toAmt(_shares, totalAssets(), totalSupply());
    }

    /// @inheritdoc ILendingPool
    function toSharesCurrent(uint _amt) external accrue returns (uint shares) {
        shares = toShares(_amt);
    }

    /// @inheritdoc ILendingPool
    function toAmtCurrent(uint _shares) external accrue returns (uint amt) {
        amt = toAmt(_shares);
    }

    /// @inheritdoc ILendingPool
    function getSupplyRate_e18() external view returns (uint supplyRate_e18) {
        uint _totalDebt = totalDebt;
        uint _cash = cash;
        uint borrowRate_e18 = IIRM(irm).getBorrowRate_e18(_cash, _totalDebt);
        // supply rate = borrow rate * (1 - reserve factor) * totalDebt / (cash + totalDebt)
        supplyRate_e18 = _cash + _totalDebt > 0
            ? (borrowRate_e18 * (ONE_E18 - reserveFactor_e18) * _totalDebt) / ((_cash + _totalDebt) * ONE_E18)
            : 0;
    }

    /// @inheritdoc ILendingPool
    function getBorrowRate_e18() external view returns (uint borrowRate_e18) {
        borrowRate_e18 = IIRM(irm).getBorrowRate_e18(cash, totalDebt);
    }

    /// @inheritdoc ILendingPool
    function totalAssets() public view returns (uint) {
        return cash + totalDebt;
    }

    /// @inheritdoc ILendingPool
    function setIrm(address _irm) external accrue onlyGuardian {
        irm = _irm;
        emit SetIrm(_irm);
    }

    /// @inheritdoc ILendingPool
    function setReserveFactor_e18(uint _reserveFactor_e18) external accrue onlyGuardian {
        reserveFactor_e18 = _reserveFactor_e18;
        emit SetReserveFactor_e18(_reserveFactor_e18);
    }

    /// @inheritdoc ILendingPool
    function setTreasury(address _treasury) external onlyGovernor {
        treasury = _treasury;
        emit SetTreasury(_treasury);
    }

    /// @dev This implementation mitigates share price manipulations, using OpenZeppelin's method of virtual shares:
    /// https://docs.openzeppelin.com/contracts/4.x/erc4626#inflation-attack.
    /// @param _amt The amount of assets to convert to shares.
    /// @param _totalAssets The total amount of assets in the pool.
    /// @param _totalShares The total amount of shares in the pool.
    /// @return shares the amount of shares
    function _toShares(uint _amt, uint _totalAssets, uint _totalShares) internal pure returns (uint shares) {
        return _amt.mulDiv(_totalShares + VIRTUAL_SHARES, _totalAssets + VIRTUAL_ASSETS);
    }

    /// @dev This implementation mitigates share price manipulations, using OpenZeppelin's method of virtual shares:
    /// https://docs.openzeppelin.com/contracts/4.x/erc4626#inflation-attack.
    /// @param _shares The amount of shares to convert to assets.
    /// @param _totalAssets The total amount of assets in the pool.
    /// @param _totalShares The total amount of shares in the pool.
    /// @return amt the token amount
    function _toAmt(uint _shares, uint _totalAssets, uint _totalShares) internal pure returns (uint amt) {
        return _shares.mulDiv(_totalAssets + VIRTUAL_ASSETS, _totalShares + VIRTUAL_SHARES);
    }
}
"},"contracts/oracle/Api3OracleReader.sol":{"content":"// SPDX-License-Identifier: None
pragma solidity ^0.8.19;

import {SafeCast} from '@openzeppelin-contracts/utils/math/SafeCast.sol';
import {IERC20Metadata} from '@openzeppelin-contracts/token/ERC20/extensions/IERC20Metadata.sol';
import {Initializable} from '@openzeppelin-contracts-upgradeable/proxy/utils/Initializable.sol';

import '../common/library/InitErrors.sol';
import '../common/library/UncheckedIncrement.sol';
import {UnderACM} from '../common/UnderACM.sol';

import {IApi3OracleReader, IBaseOracle} from '../interfaces/oracle/api3/IApi3OracleReader.sol';
import {IApi3ServerV1} from '../interfaces/oracle/api3/IApi3ServerV1.sol';

contract Api3OracleReader is IApi3OracleReader, UnderACM, Initializable {
    using SafeCast for int224;
    using UncheckedIncrement for uint;

    // constants
    uint private constant ONE_E18 = 1e18;
    bytes32 private constant GOVERNOR = keccak256('governor');

    // storages
    address public api3ServerV1; // @inheritdoc IApi3OracleReader
    mapping(address => DataFeedInfo) public dataFeedInfos; // @inheritdoc IApi3OracleReader

    // modifiers
    modifier onlyGovernor() {
        ACM.checkRole(GOVERNOR, msg.sender);
        _;
    }

    // constructor
    constructor(address _acm) UnderACM(_acm) {
        _disableInitializers();
    }

    // initializer
    /// @dev initialize contract and set api3 server v1 address
    /// @param _api3ServerV1 api3 server v1 address
    function initialize(address _api3ServerV1) external initializer {
        api3ServerV1 = _api3ServerV1;
        emit SetApi3ServerV1(_api3ServerV1);
    }

    // functions
    /// @inheritdoc IApi3OracleReader
    function setDataFeedIds(address[] calldata _tokens, bytes32[] calldata _dataFeedIds) external onlyGovernor {
        _require(_dataFeedIds.length == _tokens.length, Errors.ARRAY_LENGTH_MISMATCHED);

        for (uint i; i < _dataFeedIds.length; i = i.uinc()) {
            dataFeedInfos[_tokens[i]].dataFeedId = _dataFeedIds[i];
            emit SetDataFeed(_tokens[i], _dataFeedIds[i]);
        }
    }

    /// @inheritdoc IApi3OracleReader
    function setApi3ServerV1(address _api3ServerV1) external onlyGovernor {
        api3ServerV1 = _api3ServerV1;
        emit SetApi3ServerV1(api3ServerV1);
    }

    /// @inheritdoc IApi3OracleReader
    function setMaxStaleTimes(address[] calldata _tokens, uint[] calldata _maxStaleTimes) external onlyGovernor {
        _require(_maxStaleTimes.length == _tokens.length, Errors.ARRAY_LENGTH_MISMATCHED);

        for (uint i; i < _maxStaleTimes.length; i = i.uinc()) {
            dataFeedInfos[_tokens[i]].maxStaleTime = _maxStaleTimes[i];
            emit SetMaxStaleTime(_tokens[i], _maxStaleTimes[i]);
        }
    }

    /// @inheritdoc IBaseOracle
    function getPrice_e36(address _token) external view returns (uint price_e36) {
        // load and check
        DataFeedInfo memory dataFeedInfo = dataFeedInfos[_token];
        _require(dataFeedInfo.dataFeedId != bytes32(0), Errors.DATAFEED_ID_NOT_SET);
        _require(dataFeedInfo.maxStaleTime != 0, Errors.MAX_STALETIME_NOT_SET);

        // get price and token's decimals
        uint decimals = uint(IERC20Metadata(_token).decimals());
        // return price per token with 1e18 precisions
        // e.g. 1 BTC = 35000 * 1e18 in USD_e18 unit
        (int224 price, uint timestamp) = IApi3ServerV1(api3ServerV1).readDataFeedWithId(dataFeedInfo.dataFeedId);

        // check if the last updated is not longer than the max stale time
        _require(block.timestamp - timestamp <= dataFeedInfo.maxStaleTime, Errors.MAX_STALETIME_EXCEEDED);

        // return as [USD_e36 per wei unit]
        price_e36 = (price.toUint256() * ONE_E18) / 10 ** decimals;
    }
}
"},"contracts/oracle/InitOracle.sol":{"content":"// SPDX-License-Identifier: None
pragma solidity ^0.8.19;

import '../common/library/InitErrors.sol';
import '../common/library/UncheckedIncrement.sol';

import {UnderACM} from '../common/UnderACM.sol';

import {IInitOracle, IBaseOracle} from '../interfaces/oracle/IInitOracle.sol';
import {Initializable} from '@openzeppelin-contracts-upgradeable/proxy/utils/Initializable.sol';

contract InitOracle is IInitOracle, UnderACM, Initializable {
    using UncheckedIncrement for uint;

    // constants
    uint private constant ONE_E18 = 1e18;
    bytes32 private constant GOVERNOR = keccak256('governor');

    // storages
    mapping(address => address) public primarySources; // @inheritdoc IInitOracle
    mapping(address => address) public secondarySources; // @inheritdoc IInitOracle
    mapping(address => uint) public maxPriceDeviations_e18; // @inheritdoc IInitOracle

    // modifiers
    modifier onlyGovernor() {
        ACM.checkRole(GOVERNOR, msg.sender);
        _;
    }

    // constructor
    constructor(address _acm) UnderACM(_acm) {
        _disableInitializers();
    }

    // initializer
    /// @dev initialize the contract
    function initialize() external initializer {}

    // functions
    /// @inheritdoc IBaseOracle
    function getPrice_e36(address _token) public view returns (uint price_e36) {
        bool isPrimarySourceValid;
        bool isSecondarySourceValid;
        uint primaryPrice_e36;
        uint secondaryPrice_e36;

        // get price from primary source
        try IBaseOracle(primarySources[_token]).getPrice_e36(_token) returns (uint primaryPrice_e36_) {
            primaryPrice_e36 = primaryPrice_e36_;
            isPrimarySourceValid = true;
        } catch {}

        // get price from secondary source
        try IBaseOracle(secondarySources[_token]).getPrice_e36(_token) returns (uint secondaryPrice_e36_) {
            secondaryPrice_e36 = secondaryPrice_e36_;
            isSecondarySourceValid = true;
        } catch {}

        // normal case: both sources are valid
        // check that the prices are not too deviated
        // abnormal case: one of the sources is invalid
        // using the valid source - prioritize the primary source
        // abnormal case: both sources are invalid
        // revert
        _require(isPrimarySourceValid || isSecondarySourceValid, Errors.NO_VALID_SOURCE);
        if (isPrimarySourceValid && isSecondarySourceValid) {
            // sort Price
            (uint minPrice_e36, uint maxPrice_e36) = primaryPrice_e36 < secondaryPrice_e36
                ? (primaryPrice_e36, secondaryPrice_e36)
                : (secondaryPrice_e36, primaryPrice_e36);

            // check deviation
            _require(
                (maxPrice_e36 * ONE_E18) / minPrice_e36 <= maxPriceDeviations_e18[_token], Errors.TOO_MUCH_DEVIATION
            );
        }
        price_e36 = isPrimarySourceValid ? primaryPrice_e36 : secondaryPrice_e36;
    }

    /// @inheritdoc IInitOracle
    function getPrices_e36(address[] calldata _tokens) external view returns (uint[] memory prices_e36) {
        prices_e36 = new uint[](_tokens.length);
        for (uint i; i < _tokens.length; i = i.uinc()) {
            prices_e36[i] = getPrice_e36(_tokens[i]);
        }
    }

    /// @inheritdoc IInitOracle
    function setPrimarySources(address[] calldata _tokens, address[] calldata _sources) external onlyGovernor {
        _require(_tokens.length == _sources.length, Errors.ARRAY_LENGTH_MISMATCHED);
        for (uint i; i < _tokens.length; i = i.uinc()) {
            primarySources[_tokens[i]] = _sources[i];
            emit SetPrimarySource(_tokens[i], _sources[i]);
        }
    }

    /// @inheritdoc IInitOracle
    function setSecondarySources(address[] calldata _tokens, address[] calldata _sources) external onlyGovernor {
        _require(_tokens.length == _sources.length, Errors.ARRAY_LENGTH_MISMATCHED);
        for (uint i; i < _tokens.length; i = i.uinc()) {
            secondarySources[_tokens[i]] = _sources[i];
            emit SetSecondarySource(_tokens[i], _sources[i]);
        }
    }

    /// @inheritdoc IInitOracle
    function setMaxPriceDeviations_e18(address[] calldata _tokens, uint[] calldata _maxPriceDeviations_e18)
        external
        onlyGovernor
    {
        _require(_tokens.length == _maxPriceDeviations_e18.length, Errors.ARRAY_LENGTH_MISMATCHED);
        for (uint i; i < _tokens.length; i = i.uinc()) {
            // sanity check
            _require(_maxPriceDeviations_e18[i] >= ONE_E18, Errors.MAX_PRICE_DEVIATION_TOO_LOW);

            maxPriceDeviations_e18[_tokens[i]] = _maxPriceDeviations_e18[i];
            emit SetMaxPriceDeviation_e18(_tokens[i], _maxPriceDeviations_e18[i]);
        }
    }
}
"},"contracts/oracle/PythOracleReader.sol":{"content":"// SPDX-License-Identifier: None
pragma solidity ^0.8.19;

import {SafeCast} from '@openzeppelin-contracts/utils/math/SafeCast.sol';
import {Math} from '@openzeppelin-contracts/utils/math/Math.sol';
import {IERC20Metadata} from '@openzeppelin-contracts/token/ERC20/extensions/IERC20Metadata.sol';
import {Initializable} from '@openzeppelin-contracts-upgradeable/proxy/utils/Initializable.sol';

import '../common/library/InitErrors.sol';
import '../common/library/UncheckedIncrement.sol';
import {UnderACM} from '../common/UnderACM.sol';

import {IPyth} from '../interfaces/oracle/pyth/IPyth.sol';
import {IPythOracleReader, IBaseOracle} from '../interfaces/oracle/pyth/IPythOracleReader.sol';

contract PythOracleReader is IPythOracleReader, UnderACM, Initializable {
    using UncheckedIncrement for uint;
    using SafeCast for uint;
    using SafeCast for int;
    using Math for uint;

    // constants
    uint private constant ONE_E18 = 1e18;
    bytes32 private constant GOVERNOR = keccak256('governor');

    // storages
    mapping(address => bytes32) public priceIds; // @inheritdoc IPythOracleReader
    mapping(address => uint) public maxStaleTimes; // @inheritdoc IPythOracleReader
    address public pyth;

    // modifiers
    modifier onlyGovernor() {
        ACM.checkRole(GOVERNOR, msg.sender);
        _;
    }

    // constructor
    constructor(address _acm) UnderACM(_acm) {
        _disableInitializers();
    }

    // initializer
    /// @dev initialize contract and set pyth address
    /// @param _pyth pyth address
    function initialize(address _pyth) external initializer {
        pyth = _pyth;
        emit SetPyth(_pyth);
    }

    // functions
    /// @inheritdoc IPythOracleReader
    function setPriceIds(address[] calldata _tokens, bytes32[] calldata _priceIds) external onlyGovernor {
        _require(_priceIds.length == _tokens.length, Errors.ARRAY_LENGTH_MISMATCHED);
        for (uint i; i < _priceIds.length; i = i.uinc()) {
            priceIds[_tokens[i]] = _priceIds[i];
            emit SetPriceId(_tokens[i], _priceIds[i]);
        }
    }

    /// @inheritdoc IPythOracleReader
    function setPyth(address _pyth) external onlyGovernor {
        pyth = _pyth;
        emit SetPyth(_pyth);
    }

    /// @inheritdoc IPythOracleReader
    function setMaxStaleTimes(address[] calldata _tokens, uint[] calldata _maxStaleTimes) external onlyGovernor {
        _require(_maxStaleTimes.length == _tokens.length, Errors.ARRAY_LENGTH_MISMATCHED);

        for (uint i; i < _maxStaleTimes.length; i = i.uinc()) {
            maxStaleTimes[_tokens[i]] = _maxStaleTimes[i];
            emit SetMaxStaleTime(_tokens[i], _maxStaleTimes[i]);
        }
    }

    /// @inheritdoc IBaseOracle
    function getPrice_e36(address _token) external view returns (uint price_e36) {
        // load and check
        bytes32 priceId = priceIds[_token];
        uint maxStaleTime = maxStaleTimes[_token];
        _require(priceId != bytes32(0), Errors.NO_PRICE_ID);
        _require(maxStaleTime != 0, Errors.MAX_STALETIME_NOT_SET);

        // NOTE:
        // price: Price
        // conf: Confidence interval around the price
        // expo: Price exponent e.g. 10^8 -> expo = -8
        // publishTime: Unix timestamp describing when the price was published
        (int64 price,, int32 expo, uint64 publishTime) = IPyth(pyth).getPriceUnsafe(priceId);

        // check if the last updated is not longer than the max stale time
        _require(block.timestamp - publishTime <= maxStaleTime, Errors.MAX_STALETIME_EXCEEDED);

        // return as [USD_e36 per wei unit]
        price_e36 = int(price).toUint256() * 10 ** (36 - IERC20Metadata(_token).decimals() - uint(int(-expo)));
    }
}
"},"contracts/risk_manager/RiskManager.sol":{"content":"// SPDX-License-Identifier: None
pragma solidity ^0.8.19;

import {IRiskManager} from '../interfaces/risk_manager/IRiskManager.sol';
import {ILendingPool} from '../interfaces/lending_pool/ILendingPool.sol';
import '../common/library/InitErrors.sol';
import '../common/library/UncheckedIncrement.sol';
import {Initializable} from '@openzeppelin-contracts-upgradeable/proxy/utils/Initializable.sol';
import {SafeCast} from '@openzeppelin-contracts/utils/math/SafeCast.sol';
import {UnderACM} from '../common/UnderACM.sol';

contract RiskManager is IRiskManager, UnderACM, Initializable {
    using UncheckedIncrement for uint;
    using SafeCast for uint;
    using SafeCast for uint128;
    using SafeCast for int;

    // constants
    bytes32 private constant GUARDIAN = keccak256('guardian');

    // immutables
    address public immutable CORE; // core address

    // storages
    mapping(uint16 => mapping(address => DebtCeilingInfo)) private __modeDebtCeilingInfos;

    // modifiers
    modifier onlyGuardian() {
        ACM.checkRole(GUARDIAN, msg.sender);
        _;
    }

    modifier onlyCore() {
        _require(msg.sender == CORE, Errors.NOT_INIT_CORE);
        _;
    }

    // constructor
    constructor(address _core, address _acm) UnderACM(_acm) {
        CORE = _core;
        _disableInitializers();
    }

    // initializer
    /// @dev initialize contract
    function initialize() external initializer {}

    // functions
    /// @inheritdoc IRiskManager
    function getModeDebtShares(uint16 _mode, address _pool) external view returns (uint) {
        return __modeDebtCeilingInfos[_mode][_pool].debtShares;
    }

    /// @inheritdoc IRiskManager
    function getModeDebtAmtCurrent(uint16 _mode, address _pool) external returns (uint) {
        return ILendingPool(_pool).debtShareToAmtCurrent(__modeDebtCeilingInfos[_mode][_pool].debtShares);
    }

    /// @inheritdoc IRiskManager
    function getModeDebtAmtStored(uint16 _mode, address _pool) external view returns (uint) {
        return ILendingPool(_pool).debtShareToAmtStored(__modeDebtCeilingInfos[_mode][_pool].debtShares);
    }

    /// @inheritdoc IRiskManager
    function getModeDebtCeilingAmt(uint16 _mode, address _pool) external view returns (uint) {
        return __modeDebtCeilingInfos[_mode][_pool].ceilAmt;
    }

    /// @inheritdoc IRiskManager
    function updateModeDebtShares(uint16 _mode, address _pool, int _deltaShares) external onlyCore {
        DebtCeilingInfo memory debtCeilingInfo = __modeDebtCeilingInfos[_mode][_pool];
        uint newDebtShares = (debtCeilingInfo.debtShares.toInt256() + _deltaShares).toUint256();
        if (_deltaShares > 0) {
            uint currentDebt = ILendingPool(_pool).debtShareToAmtCurrent(newDebtShares);
            _require(currentDebt <= debtCeilingInfo.ceilAmt, Errors.DEBT_CEILING_EXCEEDED);
        }
        __modeDebtCeilingInfos[_mode][_pool].debtShares = newDebtShares.toUint128();
    }

    /// @inheritdoc IRiskManager
    function setModeDebtCeilingInfo(uint16 _mode, address[] calldata _pools, uint128[] calldata _ceilAmts)
        external
        onlyGuardian
    {
        _require(_pools.length == _ceilAmts.length, Errors.ARRAY_LENGTH_MISMATCHED);
        for (uint i; i < _pools.length; i = i.uinc()) {
            __modeDebtCeilingInfos[_mode][_pools[i]].ceilAmt = _ceilAmts[i];
            emit SetModeDebtCeilingInfo(_mode, _pools[i], _ceilAmts[i]);
        }
    }
}
